import {analyze,EXAMPLES,markdownPacket} from './engine.js';
const canvas=document.getElementById('screen'),ctx=canvas.getContext('2d');const $=id=>document.getElementById(id);let running=false;
const fellowship=analyze(EXAMPLES.fellowship.text),pantry=analyze(EXAMPLES.pantry.text);
const scenes=[
 {title:'Fine print. Clear next step.',subtitle:'AccessKit • free browser-local notice workspace',lines:['An opportunity can be available and still be hard to access.','Requirements get buried. Dates disagree. Exceptions get lost.','AccessKit turns a notice into a plan with evidence you can inspect.'],footer:'A two-minute walkthrough • fictional examples • no user-impact claims'},
 {title:'01 / Paste the original notice',subtitle:'Example: Community Builder Fellowship',lines:EXAMPLES.fellowship.text.split('\n').slice(1,7),footer:'Runs locally using transparent phrase rules. No model API or paid service.'},
 {title:'02 / A checklist, with receipts',subtitle:`Actual engine output: ${fellowship.items.length} source-linked items`,lines:fellowship.items.slice(0,6).map(i=>`[${i.sourceId}] ${i.text}`),footer:'Every result preserves the original line. Select View source in the app to inspect it.'},
 {title:'03 / Two deadlines? Ask first.',subtitle:'Actual engine output: date review',lines:fellowship.deadlines.map(d=>`${d.label} — ${d.kind}`).concat(fellowship.questions.map(q=>q.text)),footer:'Different dates may describe different stages. The app asks; it does not choose.'},
 {title:'04 / Exceptions stay visible',subtitle:'Example: Neighborhood food pantry',lines:pantry.items.filter(i=>i.group==='Access details'||i.conditional).map(i=>`[${i.sourceId}] ${i.text}`).slice(0,5).concat('No one is turned away for missing documents.'),footer:'Original wording is preserved. Conditions and negation get explicit labels.'},
 {title:'05 / Leave with an action plan',subtitle:'Real Markdown export from the same engine',lines:markdownPacket('My fellowship plan',fellowship,new Set([fellowship.items[0].id])).split('\n').filter(x=>x.startsWith('- [')).slice(0,5),footer:'Download Markdown • print • copy organizer questions • confirmed all-day calendar reminders'},
 {title:'Private by default. Honest about limits.',subtitle:'A working prototype, built with AI assistance',lines:['Notice text stays in the browser. Device saving is optional.','English phrase rules can miss or misclassify information.','Ten automated synthetic tests pass. User validation is still next.','Built with HTML, CSS, JavaScript and Node.js. Codex assistance disclosed.','Try the full interface at the project demo link.'],footer:'AccessKit ↗  •  Open source  •  Zero runtime dependencies'}
];
function wrap(text,x,y,width,size=25,color='#183f35'){ctx.font=`${size}px Arial`;ctx.fillStyle=color;const words=text.split(' ');let line='';for(const word of words){if(ctx.measureText(line+word).width>width&&line){ctx.fillText(line,x,y);y+=size*1.45;line='';}line+=word+' ';}ctx.fillText(line,x,y);return y+size*1.6;}
function draw(index,progress=0){const scene=scenes[index];ctx.fillStyle='#f6f5ef';ctx.fillRect(0,0,1440,960);ctx.fillStyle='#183f35';ctx.fillRect(0,0,1440,8);ctx.font='bold 32px Arial';ctx.fillText('AccessKit ↗',70,78);ctx.font='16px Arial';ctx.fillText('NEXT BYTE HACKS V5  /  CAPTIONED DEMO',930,75);ctx.strokeStyle='#d8ddd2';ctx.beginPath();ctx.moveTo(70,110);ctx.lineTo(1370,110);ctx.stroke();wrap(scene.title,70,205,1270,48);wrap(scene.subtitle,70,260,1250,24,'#68766b');ctx.fillStyle='#fffefa';ctx.fillRect(60,310,1320,485);let y=365;for(const line of scene.lines){y=wrap(line,95,y,1245,index===1?23:24)+18;}wrap(scene.footer,70,855,1280,22,'#68766b');ctx.fillStyle='#d8ddd2';ctx.fillRect(70,907,1300,5);ctx.fillStyle='#183f35';ctx.fillRect(70,907,1300*progress,5);ctx.font='16px Arial';ctx.fillText(`${index+1} / ${scenes.length}`,1300,940);}
function save(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function start(record){if(running)return;running=true;$('play').disabled=true;$('record').disabled=true;let recorder,chunks=[];if(record){const stream=canvas.captureStream(15);const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(x=>MediaRecorder.isTypeSupported(x));recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:1800000});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{save(new Blob(chunks,{type:'video/webm'}),'accesskit-demo.webm');stream.getTracks().forEach(t=>t.stop());};recorder.start();}const started=performance.now(),duration=123000;function frame(){const elapsed=performance.now()-started;const p=Math.min(1,elapsed/duration);const index=Math.min(scenes.length-1,Math.floor(p*scenes.length));draw(index,p);$('status').textContent=`${record?'Recording':'Playing'}: ${Math.floor(elapsed/1000)} / 123 seconds`;if(p<1)requestAnimationFrame(frame);else{if(recorder)recorder.stop();running=false;$('play').disabled=false;$('record').disabled=false;$('status').textContent='Demo complete';}}requestAnimationFrame(frame);}
$('play').onclick=()=>start(false);$('record').onclick=()=>start(true);$('save').onclick=()=>{const data=$('image').value;if(!/^data:image\/(jpeg|png);base64,/.test(data)){alert('Provide a JPEG or PNG screenshot data URL.');return;}const [header,b64]=data.split(',');const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));save(new Blob([bytes],{type:header.includes('png')?'image/png':'image/jpeg'}),'accesskit-screenshot.'+(header.includes('png')?'png':'jpg'));};draw(0);
